<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title><?php echo htmlspecialchars($title ?? 'Goods Received Note'); ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.1/dist/css/bootstrap.min.css" rel="stylesheet"><style>@media print {.no-print{display:none!important} body{padding:0!important}}</style></head><body class="p-4"><div class="container"><div class="d-flex justify-content-between align-items-start mb-4"><div><h2 class="fw-bold">Goods Received Note</h2><div>Receipt: <?php echo htmlspecialchars($receipt['receipt_number']); ?></div><div>Purchase Order: <?php echo htmlspecialchars($receipt['po_number']); ?></div></div><button class="btn btn-primary no-print" onclick="window.print()"><i class="bi bi-printer"></i> Print</button></div><div class="row mb-4"><div class="col-md-6"><strong>Supplier</strong><div><?php echo htmlspecialchars($receipt['supplier'] ?? ''); ?></div></div><div class="col-md-6"><strong>Received by</strong><div><?php echo htmlspecialchars($receipt['received_by_name'] ?? ''); ?></div><div><?php echo htmlspecialchars($receipt['received_at'] ?? ''); ?></div></div></div><table class="table table-bordered"><thead><tr><th>Item</th><th>Quantity Received</th><th>Price Rate</th><th>Total</th></tr></thead><tbody><?php foreach (($receipt['items'] ?? []) as $item): ?><tr><td><?php echo htmlspecialchars($item['product_name']); ?></td><td><?php echo number_format((float)$item['quantity_received'], 2); ?></td><td><?php echo number_format((float)$item['price_rate'], 2); ?></td><td><?php echo number_format((float)$item['quantity_received'] * (float)$item['price_rate'], 2); ?></td></tr><?php endforeach; ?></tbody></table><div class="mt-5 row"><div class="col-6">Received by: ____________________</div><div class="col-6">Checked by: ____________________</div></div></div></body></html>
